def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Early game: cooperate, but retaliate immediately if opponent defects
    if n < 10:
        if n > 0 and history[-1][1] == 'D':
            return 'D'
        return 'C'

    # Probe at round 11 (n=10)
    if n == 10:
        return 'D'

    # Wait for opponent's response to the probe
    if n == 11:
        return 'C'

    # Count opponent defections
    opp_d = 0
    for a, b in history:
        if b == 'D':
            opp_d += 1

    # If opponent is a heavy defector, defect always
    if opp_d > n * 0.4:
        return 'D'

    # Check if opponent retaliated to our probe (round 12 action)
    retaliated = (history[11][1] == 'D')

    # Recent exploitation: opponent defecting while we cooperate
    recent = history[-10:] if n >= 10 else history
    recent_cd = sum(1 for a, b in recent if a == 'C' and b == 'D')

    # Exploit mode: if opponent is not retaliatory, or is exploiting us heavily
    if (not retaliated) or (recent_cd >= 2):
        if history[-1][1] == 'D':
            return 'D'
        if n == 99:
            return 'D'
        if n % 5 == 0:
            return 'D'
        return 'C'
    else:
        # Cautious mode: cooperate, but defect on last round and punish frequent defections
        if n == 99:
            return 'D'
        if history[-1][1] == 'D':
            recent_opp_d = sum(1 for a, b in history[-5:] if b == 'D')
            if recent_opp_d >= 2:
                return 'D'
            return 'C'
        return 'C'
